  9 | const SLUG_RE = /^[a-z0-9]+(?:-[a-z0-9]+)*$/;
 10 | 
 11 | /** A "plain slug": lowercase letters/digits separated by single hyphens. No slashes, dots or "..". */
 12 | export function isSlug(id: unknown): id is string {
 13 |   return typeof id === "string" && SLUG_RE.test(id);
 14 | }
 15 | 
 16 | export function getAssignmentsDir(): string {
 17 |   return ASSIGNMENTS_DIR;
 18 | }
