 12 | export function createApp(): express.Express {
 13 |   const app = express();
 14 |   app.use(express.json({ limit: "1mb" }));
 15 | 
 16 |   app.get("/api/health", (_req, res) => {
 17 |     res.json({ status: "ok" });
 18 |   });
 19 | 
 20 |   app.get("/api/assignments", (_req, res) => {
 21 |     const assignments = listAssignments();
 22 |     res.json(
 23 |       assignments.map((a) => ({
 24 |         id: a.id,
 25 |         language: a.language,
 26 |         statement: a.statement,
 27 |         starterCode: a.starterCode,
 28 |       })),
 29 |     );
 30 |   });
 31 | 
 32 |   app.post("/api/session", async (req: Request, res: Response, next: NextFunction) => {
 33 |     try {
 34 |       const body: unknown = req.body;
 35 |       if (typeof body !== "object" || body === null || Array.isArray(body)) {
 36 |         res.status(400).json({ error: "request body must be a JSON object" });
 37 |         return;
 38 |       }
 39 | 
 40 |       const assignmentId = (body as Record<string, unknown>).assignmentId;
 41 |       if (!isSlug(assignmentId)) {
 42 |         res.status(400).json({ error: "assignmentId is required and must be a plain slug" });
 43 |         return;
 44 |       }
 45 | 
 46 |       let assignment: Assignment;
 47 |       try {
 48 |         assignment = loadAssignment(assignmentId);
 49 |       } catch {
 50 |         res.status(404).json({ error: `unknown assignment: ${assignmentId}` });
 51 |         return;
 52 |       }
 53 | 
 54 |       const codeRaw = (body as Record<string, unknown>).code;
 55 |       let code: string;
 56 |       if (codeRaw === undefined || codeRaw === null || codeRaw === "") {
 57 |         code = assignment.starterCode;
 58 |       } else if (typeof codeRaw !== "string") {
 59 |         res.status(400).json({ error: "code must be a string" });
 60 |         return;
 61 |       } else {
 62 |         code = codeRaw;
 63 |       }
 64 | 
 65 |       const testResults = await runAssignment(assignment, code);
 66 |       const sessionId = randomUUID();
 67 | 
 68 |       res.json({ sessionId, testResults });
 69 |     } catch (err) {
 70 |       next(err);
 71 |     }
 72 |   });
 73 | 
 74 |   const webDir = path.resolve(process.cwd(), "web");
 75 |   if (fs.existsSync(webDir)) {
 76 |     app.use(express.static(webDir));
 77 |   }
 78 | 
 79 |   // eslint-disable-next-line @typescript-eslint/no-explicit-any
 80 |   app.use((err: any, _req: Request, res: Response, _next: NextFunction) => {
 81 |     const status = typeof err?.status === "number" ? err.status : 500;
 82 |     if (status >= 400 && status < 500) {
 83 |       res.status(status).json({ error: "invalid request body" });
 84 |       return;
 85 |     }
 86 |     console.error(err);
 87 |     res.status(500).json({ error: "internal server error" });
 88 |   });
 89 | 
 90 |   return app;
 91 | }
