 58 | interface TableResult {
 59 |   build: { ok: boolean; stderr: string } | null;
 60 |   tests: { name: string; expected: string; got: string; timedOut: boolean; passed: boolean }[];
 61 |   passed: number;
 62 |   total: number;
 63 | }
