 65 | function printTestTable(id: string, assignment: Assignment, result: TableResult): void {
 66 |   console.log(`\n=== ${id} (${assignment.language}) ===`);
 67 |   if (result.build) {
 68 |     console.log(`  build: ${result.build.ok ? "ok" : "FAILED"}`);
 69 |     if (!result.build.ok && result.build.stderr.trim()) {
 70 |       console.log(`  build stderr: ${result.build.stderr.trim().split("\n")[0]}`);
 71 |     }
 72 |   } else {
 73 |     console.log(`  build: none`);
 74 |   }
 75 |   for (const t of result.tests) {
 76 |     const tag = t.timedOut ? "TIMEOUT" : t.passed ? "PASS" : "FAIL";
 77 |     console.log(
 78 |       `  [${tag.padEnd(7)}] ${t.name.padEnd(16)} expected=${JSON.stringify(t.expected).padEnd(8)} got=${JSON.stringify(t.got).padEnd(8)}`,
 79 |     );
 80 |   }
 81 |   console.log(`  -> ${result.passed}/${result.total} passed`);
 82 | }
