 84 | async function main(): Promise<void> {
 85 |   // 1. Buggy starter programs must fail exactly as expected.
 86 |   for (const id of ASSIGNMENT_IDS) {
 87 |     const assignment = loadAssignment(id);
 88 |     const result = await runAssignment(assignment, assignment.starterCode, { cleanup: true });
 89 |     printTestTable(id, assignment, result);
 90 | 
 91 |     const exp = buggyExpectations[id];
 92 |     check(result.tests.length === exp.length, `${id}: ${exp.length} tests ran`);
 93 |     for (let i = 0; i < exp.length; i++) {
 94 |       const t = result.tests[i];
 95 |       if (!t) {
 96 |         check(false, `${id}: missing test result #${i}`);
 97 |         continue;
 98 |       }
 99 |       check(t.got === exp[i].got, `${id}/${t.name}: got=${JSON.stringify(t.got)} (expected ${JSON.stringify(exp[i].got)})`);
100 |       check(t.passed === exp[i].passed, `${id}/${t.name}: passed=${t.passed} (expected ${exp[i].passed})`);
101 |     }
102 |     check(result.passed === expectedPassCount[id], `${id}: ${result.passed}/${result.total} passed (expected ${expectedPassCount[id]})`);
103 |   }
104 | 
105 |   // 2. Correct solutions must pass every test.
106 |   for (const id of ASSIGNMENT_IDS) {
107 |     const assignment = loadAssignment(id);
108 |     const result = await runAssignment(assignment, correctSolutions[id], { cleanup: true });
109 |     console.log(`\n=== ${id} (correct solution) ===`);
110 |     for (const t of result.tests) {
111 |       console.log(`  [${t.passed ? "PASS" : "FAIL"}] ${t.name} got=${JSON.stringify(t.got)}`);
112 |     }
113 |     if (result.build && !result.build.ok) {
114 |       check(false, `${id} correct solution build failed: ${result.build.stderr}`);
115 |     }
116 |     check(result.total > 0 && result.passed === result.total, `${id} correct solution passes all ${result.total} tests`);
117 |   }
118 | 
119 |   // 3. Infinite loop must be reported as timed out.
120 |   {
121 |     const assignment = loadAssignment("sum-of-list");
122 |     const result = await runAssignment(assignment, infiniteLoop, { cleanup: true, runTimeoutMs: 1000 });
123 |     console.log(`\n=== infinite loop (sum-of-list) ===`);
124 |     for (const t of result.tests) {
125 |       console.log(`  [${t.timedOut ? "TIMEOUT" : "no-timeout"}] ${t.name}`);
126 |     }
127 |     check(result.total > 0, "infinite loop ran at least one test");
128 |     check(result.tests.every((t) => t.timedOut && !t.passed), "infinite loop: every test timed out and failed");
129 |   }
