131 |   // 4. C program with a compile error must be reported as a build failure.
132 |   {
133 |     const assignment = loadAssignment("average-marks");
134 |     const result = await runAssignment(assignment, badC, { cleanup: true });
135 |     console.log(`\n=== C compile error (average-marks) ===`);
136 |     const stderr = (result.build?.stderr ?? "").trim();
137 |     console.log(`  build.ok=${result.build?.ok} timedOut=${result.build?.timedOut}`);
138 |     if (stderr) console.log(`  stderr (first line): ${stderr.split("\n")[0]}`);
139 |     check(result.build !== null, "compile error: build step ran");
140 |     check(result.build !== null && result.build.ok === false, "compile error: build reported failure");
141 |     check(result.build !== null && /error/.test(result.build.stderr), "compile error: stderr contains 'error'");
142 |     check(result.total === 0, "compile error: no tests ran (total 0)");
143 |   }
144 | 
145 |   console.log(`\n${failures === 0 ? "ALL CHECKS PASSED" : `${failures} CHECK(S) FAILED`}`);
146 |   process.exit(failures === 0 ? 0 : 1);
147 | }
148 | 
149 | main().catch((err) => {
150 |   console.error(err);
151 |   process.exit(1);
152 | });
