 1 | // RUNS WITHOUT AN API KEY: scripted fake model drives the real Cline SDK agent loop.
 2 | import { Agent, createTool } from "@cline/sdk"
 3 | import type { AgentModel, AgentModelRequest } from "@cline/agents"
 4 | import { z } from "zod"
 5 | 
 6 | const giveHint = createTool({
 7 |   name: "give_hint",
 8 |   description: "Give the student one hint at the given level (1 nudge, 2 location, 3 concept). Never include corrected code.",
 9 |   inputSchema: z.object({ level: z.number().int().min(1).max(3), tag: z.string(), text: z.string() }),
10 |   async execute(input) { return { shown: true, ...input } },
11 | })
12 | const runTests = createTool({
13 |   name: "run_tests",
14 |   description: "Run the assignment test cases against the student's submission.",
15 |   inputSchema: z.object({ assignmentId: z.string() }),
16 |   async execute(input) { return { assignmentId: input.assignmentId, passed: 2, failed: 1 } },
17 | })
18 | const editFile = createTool({
19 |   name: "edit_file",
20 |   description: "Edit a file (must be disabled in HintLab).",
21 |   inputSchema: z.object({ path: z.string(), content: z.string() }),
22 |   async execute() { editExecuted = true; return { edited: true } },
23 | })
24 | 
25 | let call = 0
26 | const seenToolNames: string[][] = []
27 | const model: AgentModel = {
28 |   async *stream(req: AgentModelRequest) {
29 |     seenToolNames.push(req.tools.map((t) => t.name))
30 |     call++
31 |     if (call === 1) {
32 |       yield { type: "text-delta", text: "Running tests first. " }
33 |       yield { type: "tool-call-delta", toolCallId: "c1", toolName: "run_tests", input: { assignmentId: "sum-of-list" } }
34 |       yield { type: "finish", reason: "tool-calls" }
35 |     } else if (call === 2) {
36 |       yield { type: "tool-call-delta", toolCallId: "cx", toolName: "edit_file", input: { path: "main.py", content: "fixed" } }
37 |       yield { type: "finish", reason: "tool-calls" }
38 |     } else if (call === 3) {
39 |       yield { type: "tool-call-delta", toolCallId: "c2", toolName: "give_hint", input: { level: 1, tag: "off-by-one", text: "Check which indices your loop visits." } }
40 |       yield { type: "finish", reason: "tool-calls" }
41 |     } else {
42 |       yield { type: "text-delta", text: "Done." }
43 |       yield { type: "finish", reason: "stop" }
44 |     }
45 |   },
46 | }
47 | 
48 | const approvals: string[] = []
49 | const agent = new Agent({
50 |   model,
51 |   systemPrompt: "You are HintLab.",
52 |   tools: [runTests, giveHint, editFile],
53 |   toolPolicies: {
54 |     edit_file: { enabled: false },
55 |     run_tests: { autoApprove: false },
56 |     give_hint: { autoApprove: true },
57 |   },
58 |   requestToolApproval: async (req) => {
59 |     approvals.push(`${req.toolName} ${JSON.stringify(req.input)}`)
60 |     return { approved: req.toolName === "run_tests" }
61 |   },
62 | })
63 | 
64 | const events: string[] = []
65 | let editExecuted = false
66 | agent.subscribe((e) => {
67 |   events.push(e.type)
68 |   if (e.type === "tool-finished") console.log("tool-finished:", e.toolCall.toolName, JSON.stringify(e.message.content).slice(0, 200))
69 | })
70 | 
71 | const result = await agent.run("Debug submission for sum-of-list")
72 | console.log("status:", result.status, "iterations:", result.iterations, "output:", JSON.stringify(result.outputText))
73 | console.log("tools model saw per call:", JSON.stringify(seenToolNames))
74 | console.log("approval requests:", approvals)
75 | console.log("edit_file executed?", editExecuted)
76 | console.log("event types:", [...new Set(events)].join(", "))

