        client: "client";
        provider: "provider";
    }>>;
    input: z.ZodUnknown;
    output: z.ZodUnknown;
    error: z.ZodOptional<z.ZodString>;
    durationMs: z.ZodNumber;
    startedAt: z.ZodDate;
    endedAt: z.ZodDate;
}, z.core.$strip>;

