**allowlist.ts**:

```ts
// HintLab run_commands allow-list.
// run_commands executes on the HOST, so this allow-list is the only protection
// between the model and arbitrary shell. It is exported so scripts/check-agent.ts
// can unit-test it.

export interface AllowDecision {
  allowed: boolean;
  reason?: string;
}

// Always-forbidden substrings. These are checked on every command BEFORE the
// whitelist match, so even a command that happens to match a structural regex
// (e.g. an echo payload) is still rejected if it smuggles shell metacharacters.
export const DENY_SUBSTRINGS: readonly string[] = [
  ";",   // command separator
  "&&",  // and-list
  "||",  // or-list
  "`",   // command substitution
  "$(",  // command substitution
  "${",  // parameter expansion
  ">",   // output redirection (writing files)
  "&",   // backgrounding / and (catches a lone & as well as &&)
  "\n",  // literal newline = another command
  "\r",
  "*",   // glob expansion
  "?",   // glob expansion
];

// Whitelist. Each command (trimmed) must match exactly one of these.
export const ALLOWED_COMMANDS: readonly RegExp[] = [
  // --- Python ---
  /^python3 main\.py$/,
  /^python3 main\.py < [A-Za-z0-9_.-]+$/,               // stdin redirect from a simple file in the workdir
  /^(echo|printf) [^|<>]+ \| python3 main\.py$/,        // pipe literal input
  // --- C ---
  /^gcc -Wall -O0 main\.c -o main$/,                    // exact tests.json build command
  /^\.\/main$/,
  /^\.\/main < [A-Za-z0-9_.-]+$/,
  /^(echo|printf) [^|<>]+ \| \.\/main$/,
  // --- Reads ---
  /^cat (main\.py|main\.c|tests\.json)$/,
];

export function extractCommands(input: unknown): string[] {
  if (input == null) return [];
  const obj = input as Record<string, unknown>;
  const raw = obj.commands ?? input;
  if (Array.isArray(raw)) {
    return raw.map((c) => (typeof c === "string" ? c : (c as any)?.command ?? "")).filter((c) => typeof c === "string");
  }
  if (typeof raw === "string") return [raw];
  if (raw && typeof raw === "object") {
    const c = (raw as any).command;
    if (typeof c === "string") return [c];
  }
  return [];
}

export function allowCommand(command: string): AllowDecision {
  const cmd = command.trim();
  if (!cmd) return { allowed: false, reason: "empty command" };
  for (const sub of DENY_SUBSTRINGS) {
    if (cmd.includes(sub)) {
      return { allowed: false, reason: `forbidden token: ${JSON.stringify(sub)}` };
    }
  }
  if (!ALLOWED_COMMANDS.some((re) => re.test(cmd))) {
    return { allowed: false, reason: "command not on the HintLab allow-list" };
  }
  return { allowed: true };
}

export function allowCommands(commands: string[]): AllowDecision {
  if (commands.length === 0) return { allowed: false, reason: "no commands provided" };
  for (const c of commands) {
    const d = allowCommand(c);
    if (!d.allowed) return d;
  }
  return { allowed: true };
}
```

