function looksLikeCodeLine(line: string): boolean {
  const s = line.trim();
  if (!s) return false;
  // definite statement keywords (prose rarely starts a line with these, except in code)
  if (/^(def|class|import|from|print|printf|scanf|return|#include|else|elif)\b/.test(s)) return true;
  // C control structures with parens
  if (/^(for|while|if)\s*\(/.test(s)) return true;
  // Python control structures ending in colon
  if (/^(for|while|if|elif|else)\b/.test(s) && /:$/.test(s)) return true;
  // function calls with arguments that look like code
  if (/\b(range|len|sum|print|printf|scanf|input|append|split|map|list|int|float|str|lower|replace|strip|reversed|enumerate|zip|sorted|min|max)\s*\([^)]/.test(s)) return true;
  // assignment statements
  if (/[a-zA-Z_]\w*\s*(?:=|\+=|-=|\*=|\/=|%=)\s*[^=]/.test(s)) return true;
  // C declarations
  if (/\b(int|float|double|char|void)\s+\w+\s*[=;(]/.test(s)) return true;
  // trailing semicolon (C statement)
  if (/;\s*$/.test(s)) return true;
  return false;
}
```

