function handleCoreEvent(e: any) {
  const sessionId = e?.payload?.sessionId;
  if (!sessionId) return;
  const session = getSession(sessionId);
  if (!session) return;
  if (e.type === "agent_event") {
    const ev = e.payload.event;
    switch (ev?.type) {
      case "content_start":
        if (ev.contentType === "tool") emitEvent(session, "tool_call", { toolName: ev.toolName, toolCallId: ev.toolCallId, input: ev.input });
        else if (ev.contentType === "text") emitEvent(session, "agent_text", { text: ev.text ?? "", phase: "start" });
        else if (ev.contentType === "reasoning") emitEvent(session, "reasoning", { text: ev.reasoning ?? "", redacted: ev.redacted });
        break;
      case "content_update":
        if (ev.contentType === "tool") emitEvent(session, "tool_call", { toolName: ev.toolName, toolCallId: ev.toolCallId, update: ev.update });
        break;
      case "content_end":
        if (ev.contentType === "tool") emitEvent(session, "tool_result", { toolName: ev.toolName, toolCallId: ev.toolCallId, output: ev.output, error: ev.error, durationMs: ev.durationMs });
        else if (ev.contentType === "text") emitEvent(session, "agent_text", { text: ev.text ?? "", phase: "end" });
        else if (ev.contentType === "reasoning") emitEvent(session, "reasoning", { text: ev.reasoning ?? "", redacted: ev.redacted, phase: "end" });
        break;
      case "iteration_start":
        emitEvent(session, "status", { iteration: ev.iteration, phase: "iteration_start" });
        break;
      case "iteration_end":
        emitEvent(session, "status", { iteration: ev.iteration, toolCallCount: ev.toolCallCount, phase: "iteration_end" });
        break;
      case "usage":
        emitEvent(session, "status", { usage: { inputTokens: ev.inputTokens, outputTokens: ev.outputTokens, totalInputTokens: ev.totalInputTokens, totalOutputTokens: ev.totalOutputTokens } });
        break;
      case "notice":
        emitEvent(session, "status", { noticeType: ev.noticeType, message: ev.message });
        break;
      case "done":
        emitEvent(session, "done", { reason: ev.reason, text: ev.text, iterations: ev.iterations });
        setStatus(session, session.hints.length >= 3 ? "complete" : "idle");
        break;
      case "error":
        emitEvent(session, "error", { message: ev.error?.message ?? String(ev.error), recoverable: ev.recoverable, iteration: ev.iteration });
        break;
    }
  } else if (e.type === "chunk") {
    // ignore per-token chunks (tool results carry output; text carried via content_start/end)
  } else if (e.type === "status") {
    emitEvent(session, "status", { status: e.payload.status });
  } else if (e.type === "ended") {
    emitEvent(session, "done", { reason: e.payload.reason });
  } else if (e.type === "hook") {
    emitEvent(session, "status", { hook: e.payload.hookEventName, toolName: e.payload.toolName });
  }
}
