  const session = getSession(sessionId);
  if (!session) return;
  const cline = await getCline();
  const mainFile = session.language === "python" ? "main.py" : "main.c";
  const mainPath = path.resolve(session.workdir, mainFile);
  const testsPath = path.resolve(session.workdir, "tests.json");
  const prompt = buildFirstPrompt(session, mainPath, testsPath);
  session.busy = true;
  setStatus(session, "running");
  try {
    const result = await cline.start({
      interactive: true,
      prompt,
      config: {
        sessionId: session.id,
        providerId: HINTLAB_PROVIDER_ID,
        modelId: HINTLAB_MODEL_ID,
        temperature: 0,
        systemPrompt: SYSTEM_PROMPT,
        cwd: session.workdir,
        workspaceRoot: session.workdir,
        enableTools: true,
        enableSpawnAgent: false,
        enableAgentTeams: false,
        extraTools: [giveHintTool as unknown as AgentTool],
      },
      toolPolicies: toolPolicies(),
      capabilities: capabilities(),
    });
    session.agentSessionId = result.sessionId;
    registerAgentSession(result.sessionId, session);
    emitEvent(session, "status", { message: "agent turn finished", finishReason: (result.result as any)?.finishReason ?? (result.result as any)?.status });
  } catch (err) {
    emitEvent(session, "error", { message: (err as Error).message });
    setStatus(session, "error");
  } finally {
    session.busy = false;
    if (session.status !== "error" && session.hints.length >= 3) setStatus(session, "complete");
    else if (session.status !== "error") setStatus(session, "idle");
  }
}
