export async function nextHint(sessionId: string): Promise<{ level: number; status: string; message?: string }> {
  const session = getSession(sessionId);
  if (!session) throw new Error("unknown session");
  if (session.busy) { const e:any = new Error("agent busy"); e.status = 409; throw e; }
  if (session.hints.length >= 3) {
    return { level: 3, status: "complete", message: "All three hint levels have already been delivered." };
  }
  const nextLevel = Math.min(session.hints.length + 1, 3);
  session.currentHintLevel = nextLevel;
  session.busy = true;
  setStatus(session, "running");
  const cline = await getCline();
  try {
    const result = await cline.send({ sessionId: session.agentSessionId ?? session.id, prompt: buildNextPrompt(session, nextLevel) });
    emitEvent(session, "status", { message: `level ${nextLevel} turn finished`, finishReason: (result as any)?.finishReason ?? (result as any)?.status });
  } catch (err) {
    emitEvent(session, "error", { message: (err as Error).message });
    setStatus(session, "error");
  } finally {
