```ts
import fs from "node:fs";
import path from "node:path";
import { randomUUID } from "node:crypto";
import type { Response } from "express";
import type { Hint, RunResult, SessionEvent, Session } from "./types";
import { SESSION_TTL_MS, SESSION_CLEANUP_INTERVAL_MS } from "./config";
import { writeSse } from "./sse";

const sessions = new Map<string, Session>();
const agentIdIndex = new Map<string, string>(); // agentSessionId -> hintlab session id

let stopAgentHook: ((agentSessionId: string) => void) | null = null;
export function setStopAgentHook(fn: (agentSessionId: string) => void): void { stopAgentHook = fn; }

export function createSession(init: { assignmentId, language, statement, workdir, testResults }): Session {
  const session: Session = {
    id: randomUUID(),
    assignmentId, language, statement, workdir, testResults,
    hints: [], events: [], status: "created",
    busy: false, currentHintLevel: 1,
    sseClients: new Set(),
    createdAt: Date.now(), lastActiveAt: Date.now(),
  };
  sessions.set(session.id, session);
  return session;
}

export function getSession(id: string): Session | undefined {
  return sessions.get(id) ?? (agentIdIndex.has(id) ? sessions.get(agentIdIndex.get(id)!) : undefined);
}

export function registerAgentSession(agentSessionId: string, sessionId: string): void {
  agentIdIndex.set(agentSessionId, sessionId);
}

export function emitEvent(session: Session, name: string, data: unknown): void {
  const event: SessionEvent = { name, data, at: Date.now() };
  session.events.push(event);
  session.lastActiveAt = Date.now();
  for (const res of session.sseClients) {
    try { writeSse(res, name, data); } catch { /* ignore */ }
  }
}

export function setStatus(session: Session, status: string): void {
  if (session.status === status) return;
  session.status = status;
  session.lastActiveAt = Date.now();
  emitEvent(session, "status", { status });
}

export function addClient(session: Session, res: Response): void {
  session.sseClients.add(res);
  session.lastActiveAt = Date.now();
  // Replay buffered events (synchronous, single-threaded → no race with broadcast).
  for (const event of session.events) {
    try { writeSse(res, event.name, event.data); } catch { break; }
  }
}

export function removeClient(session: Session, res: Response): void {
  session.sseClients.delete(res);
}

export function deleteSession(id: string): void {
  const session = getSession(id);
  if (!session) return;
  sessions.delete(session.id);
  if (session.agentSessionId) agentIdIndex.delete(session.agentSessionId);
  for (const res of session.sseClients) {
    try { res.end(); } catch { /* ignore */ }
  }
  session.sseClients.clear();
  if (session.workdir) {
    try { fs.rmSync(session.workdir, { recursive: true, force: true }); } catch { /* ignore */ }
  }
  if (session.agentSessionId) {
    try { stopAgentHook?.(session.agentSessionId); } catch { /* ignore */ }
  }
}

export function startCleanupLoop(): void {
  setInterval(() => {
    const now = Date.now();
    for (const session of [...sessions.values()]) {
      if (now - session.lastActiveAt > SESSION_TTL_MS) {
        deleteSession(session.id);
      }
    }
  }, SESSION_CLEANUP_INTERVAL_MS).unref();
}
```

