```ts
function makeWaiter() {
  const listeners = [];
  let seen = [];
  return {
    push(ev) { seen.push(ev); listeners.slice().forEach(fn => fn(ev)); listeners.length = 0; },
    wait(pred, timeoutMs) {
      const already = seen.find(pred);
      if (already) return Promise.resolve(already);
      return new Promise((resolve, reject) => {
        const t = setTimeout(() => reject(new Error("timeout waiting for event")), timeoutMs);
        listeners.push((ev) => { if (pred(ev)) { clearTimeout(t); resolve(ev); } });
      });
    },
  };
}
