/**
 * HintLab run_commands allow-list.
 *
 * `run_commands` executes on the HOST (inside the session workdir), so this
 * allow-list is the only thing standing between the model and an arbitrary
 * shell. It is deliberately strict and exported so scripts/check-agent.ts can
 * unit-test it.
 */

export interface AllowDecision {
  allowed: boolean;
  reason?: string;
}

/**
 * Substrings that are rejected on every command before the whitelist match runs.
 * This is defence-in-depth: even a command that happens to satisfy a structural
 * regex (for example the free-form payload of an `echo ... | python3 main.py`)
 * is still rejected if it smuggles shell metacharacters.
 */
export const DENY_SUBSTRINGS: readonly string[] = [
  ";", // command separator
  "&&", // and-list
  "||", // or-list
  "`", // command substitution
  "$(", // command substitution
  "${", // parameter expansion
  ">", // output redirection (writing files)
  "&", // backgrounding / single ampersand
  "\n", // literal newline = another command
  "\r", // literal carriage return
  "*", // glob expansion
  "?", // glob expansion
];

/**
 * The whitelist. Each trimmed command must match exactly one of these anchored
 * patterns. Only the assignment's own build/run/read commands are allowed.
 */
export const ALLOWED_COMMANDS: readonly RegExp[] = [
  // --- Python: run the program ---
  /^python3 main\.py$/,
  // stdin redirect from a simple file name (no slashes → cannot escape the workdir)
  /^python3 main\.py < [A-Za-z0-9_.-]+$/,
  // pipe literal input into the program (echo/printf only; no nested pipes/redirects)
  /^(echo|printf) [^|<>]+ \| python3 main\.py$/,
  // --- C: build + run ---
  /^gcc -Wall -O0 main\.c -o main$/, // the exact tests.json build command
  /^\.\/main$/,
  /^\.\/main < [A-Za-z0-9_.-]+$/,
  /^(echo|printf) [^|<>]+ \| \.\/main$/,
  // --- Reads ---
  /^cat (main\.py|main\.c|tests\.json)$/,
];

/**
 * Normalise the (loosely-typed) run_commands input into a flat list of command
 * strings. Handles both the simple `{ commands: string[] }` shape and the
 * structured `{ command, args }` / string forms the SDK accepts.
 */
export function extractCommands(input: unknown): string[] {
  if (input == null) return [];
  const obj = input as Record<string, unknown>;
  const raw: unknown = "commands" in obj ? obj.commands : input;

  if (Array.isArray(raw)) {
    return raw
      .map((c): string | undefined => {
        if (typeof c === "string") return c;
        if (c && typeof c === "object") return (c as Record<string, unknown>).command as string | undefined;
        return undefined;
      })
      .filter((c): c is string => typeof c === "string" && c.trim().length > 0);
  }

  if (typeof raw === "string") return [raw];
  if (raw && typeof raw === "object") {
    const c = (raw as Record<string, unknown>).command;
    if (typeof c === "string") return [c];
  }
  return [];
}

/** Decide whether a single (trimmed) command is allowed. */
export function allowCommand(command: string): AllowDecision {
  const cmd = command.trim();
  if (!cmd) return { allowed: false, reason: "empty command" };

  for (const sub of DENY_SUBSTRINGS) {
    if (cmd.includes(sub)) {
      return { allowed: false, reason: `forbidden token ${JSON.stringify(sub)}` };
    }
  }

  if (!ALLOWED_COMMANDS.some((re) => re.test(cmd))) {
    return { allowed: false, reason: "command not on the HintLab allow-list" };
  }

  return { allowed: true };
}

/** Decide whether a list of commands is allowed (every command must be allowed). */
export function allowCommands(commands: string[]): AllowDecision {
  if (commands.length === 0) return { allowed: false, reason: "no commands provided" };
  for (const c of commands) {
    const d = allowCommand(c);
    if (!d.allowed) return d;
  }
  return { allowed: true };
}

/**
 * HintLab hint guard.
 *
 * Before a hint is stored or sent to the student, it is checked here. If it
 * contains a fenced code block, inline code that is more than a short
 * identifier/expression, multiple source-code-like lines, or anything that looks
 * like a rewritten solution, it is rejected (and give_hint returns an error so
 * the model rephrases without code).
 */

export interface HintCheck {
  ok: boolean;
  reason?: string;
}

/** Builtins whose `name(` form is a strong signal of a code expression. */
const CODE_FUNCTION_RE =
  /\b(?:range|len|sum|print|printf|scanf|input|append|split|map|list|int|float|str|lower|replace|strip|reversed|enumerate|zip|sorted|min|max|open|read|write|fgets|puts|puts)\s*\(/;

/** A single line that looks like actual source code / a rewritten solution. */
const CODE_LINE_PATTERNS: readonly RegExp[] = [
  /^\s*(def|class|import|from|return|print|printf|scanf|#include|else|elif)\b/,
  /^\s*(for|while|if)\s*\(/, // C control structures
  /^\s*(for|while|if|elif|else)\b[^:]*:$/, // Python control structures ending in ":"
  /\bfor\s+\w+\s+in\s/, // Python for ... in
  CODE_FUNCTION_RE,
  /[A-Za-z_]\w*\s*(?:=|\+=|-=|\*=|\/=|%=)\s*[^=]/, // assignment
  /\b(?:int|float|double|char|void|long|short|unsigned)\s+\w+\s*[=;(\[]/, // C declaration
  /(?:\(float\)|\(int\)|\(double\)|\(char\))/, // C casts (e.g. (float) sum / n)
  /;\s*$/, // trailing semicolon (C statement)
  /->/, // C struct/member dereference
];

function looksLikeCodeLine(line: string): boolean {
  const s = line.trim();
  if (!s) return false;
  return CODE_LINE_PATTERNS.some((re) => re.test(s));
}

/**
 * Check a hint's text. Returns `{ ok: true }` when it is safe to show, otherwise
 * `{ ok: false, reason }` describing what made it look like code.
 */
export function checkHint(text: string): HintCheck {
  const t = text.trim();
  if (!t) return { ok: false, reason: "empty hint" };

  // 1. Fenced code blocks.
  if (t.includes("```")) {
    return { ok: false, reason: "contains a fenced code block" };
  }

  // 2. Inline code spans: allow only a short identifier/expression.
  const inline = t.matchAll(/`([^`\n]+)`/g);
  for (const m of inline) {
    const code = m[1].trim();
    if (code.length > 20) {
      return { ok: false, reason: "inline code is longer than a short identifier/expression" };
    }
    // Reject inline code that is clearly an expression rather than a plain name.
    if (/[(){}=<>;,]|->/.test(code)) {
      return { ok: false, reason: "inline code looks like an expression" };
    }
  }

  // 3. Any line that looks like source code / a rewritten solution.
  const lines = t.split("\n");
  if (lines.some(looksLikeCodeLine)) {
    return { ok: false, reason: "text looks like source code or a rewritten solution" };
  }

  return { ok: true };
}

